use forge_template :: Element ; use serde_json :: to_string_pretty ; use crate :: context :: ContextMessage ; use crate :: conversation :: Conversation ; use forge_test_kit :: json_fixture ; use super :: * ; # [doc = " Renders a conversation as an HTML document"] # [doc = ""] # [doc = " Creates a complete HTML page displaying the conversation's information"] # [doc = " including:"] # [doc = " - Basic information (ID, title)"] # [doc = " - Reasoning configuration"] # [doc = " - Usage statistics (token counts and costs)"] # [doc = " - Context messages with tool calls and reasoning details"] # [doc = " - Available tools"] # [doc = " - Error styling for tool call failures"] # [doc = ""] # [doc = " # Arguments"] # [doc = ""] # [doc = " * `conversation` - The conversation to render"] pub fn render_conversation_html (conversation : & Conversation) -> String { let c_title = format ! ("Title: {}" , conversation . title . clone () . unwrap_or (conversation . id . to_string ())) ; let html = Element :: new ("html") . attr ("lang" , "en") . append (Element :: new ("head") . append (Element :: new ("meta") . attr ("charset" , "UTF-8")) . append (Element :: new ("meta") . attr ("name" , "viewport") . attr ("content" , "width=device-width, initial-scale=1.0") ,) . append (Element :: new ("title") . text (& c_title)) . append (Element :: new ("style") . text (include_str ! ("conversation_style.css"))) ,) . append (Element :: new ("body") . append (create_info_table (conversation)) . append (create_conversation_context_section (conversation)) . append (create_tools_section (conversation)) ,) ; format ! ("<!DOCTYPE html>\n{}" , html . render ()) }